  ]$catalog$::jsonb) as x(
    id text, slug text, dir text, name text, category text, muscle text,
    secondary jsonb, equipment text, difficulty text, "howTo" text,
    cues jsonb, mistakes jsonb
  )
)
insert into public.workout_exercises (
  id, name, normalized_name, aliases, category, primary_muscle_group,
  secondary_muscle_groups, equipment, difficulty, video, execution_notes,
  source_workbooks, source_references, status, image_url, how_to, cues,
  common_mistakes
)
select
  id,
  name,
  name,
  '{}'::text[],
  category,
  muscle,
  array(select jsonb_array_elements_text(secondary)),
  equipment,
  difficulty,
  jsonb_build_object(
    'url', format('https://start.elicohenfitness.co.il/exercises/%s/%s.mp4', dir, slug),
    'provider', 'self-hosted',
    'title', name
  ),
  "howTo",
  array['LIFE FIT professional gap audit', 'ACE Exercise Library', 'NASM Exercise Library']::text[],
  jsonb_build_array(
    jsonb_build_object('workbook', 'ACE Exercise Library', 'sheet', 'professional reference', 'cell', 'https://www.acefitness.org/resources/everyone/exercise-library/', 'name', name),
    jsonb_build_object('workbook', 'NASM Exercise Library', 'sheet', 'professional reference', 'cell', 'https://www.nasm.org/workout-exercise-guidance', 'name', name)
  ),
  'active',
  format('https://start.elicohenfitness.co.il/exercises/%s/%s.jpg', dir, slug),
  "howTo",
  array(select jsonb_array_elements_text(cues)),
  array(select jsonb_array_elements_text(mistakes))
from catalog
on conflict (id) do nothing;

commit;
